// Custom memory stream structure
struct mem_stream {
    const uint8_t* data;
    size_t size;
    size_t pos;
};

// Memory read function
static tmsize_t  id_000018_mem_read(thandle_t handle, void* buf, tmsize_t size) {
    mem_stream* ms = (mem_stream*)handle;
    tmsize_t n = size;
    if (ms->pos + n > ms->size) {
        n = ms->size - ms->pos;
    }
    if (n > 0) {
        memcpy(buf, ms->data + ms->pos, n);
        ms->pos += n;
    }
    return n;
}

// Memory write function (unused but required)
static tmsize_t  id_000018_mem_write(thandle_t handle, void* buf, tmsize_t size) {
    return 0;
}

// Memory seek function
static toff_t  id_000018_mem_seek(thandle_t handle, toff_t offset, int whence) {
    mem_stream* ms = (mem_stream*)handle;
    switch (whence) {
        case SEEK_SET:
            ms->pos = offset;
            break;
        case SEEK_CUR:
            ms->pos += offset;
            break;
        case SEEK_END:
            ms->pos = ms->size + offset;
            break;
    }
    if (ms->pos > ms->size) ms->pos = ms->size;
    return ms->pos;
}

// Memory close function
static int  id_000018_mem_close(thandle_t handle) {
    // Nothing to clean up for memory stream
    return 0;
}

